/* === Deep Focus Safe Storage & Quota Recovery === */
(function() {
  if (typeof window === "undefined" || window.__DF_SAFE_STORAGE_READY__) return;
  window.__DF_SAFE_STORAGE_READY__ = true;

  const PROTECTED_PREFIX = "zen_fortress_";
  window.dfSafeStorage = {
    getItem(key, fallback = null) {
      try {
        const v = localStorage.getItem(key);
        return v === null ? fallback : v;
      } catch (e) {
        if (window.__dfRecordError) window.__dfRecordError("storageGet", e);
        return fallback;
      }
    },
    setItem(key, value) {
      try {
        localStorage.setItem(key, String(value));
        return true;
      } catch (e) {
        // On QuotaExceededError, prune only transient non-v21 cache keys and retry once
        try {
          for (let i = localStorage.length - 1; i >= 0; i--) {
            const k = localStorage.key(i);
            if (k && !k.startsWith(PROTECTED_PREFIX) && (k.startsWith("df_transient_") || k.startsWith("df_cache_"))) {
              localStorage.removeItem(k);
            }
          }
          localStorage.setItem(key, String(value));
          return true;
        } catch (retryErr) {
          if (window.__dfRecordError) window.__dfRecordError("storageSet", retryErr);
          return false;
        }
      }
    },
    getJson(key, fallback = null) {
      try {
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
      } catch (e) {
        return fallback;
      }
    },
    setJson(key, obj) {
      try {
        return this.setItem(key, JSON.stringify(obj));
      } catch (e) {
        return false;
      }
    }
  };
})();

/* === Deep Focus M23/M24/M31/M36 Language Policy & Visibility Reconciliation === */
(function() {
  if (typeof window === "undefined" || window.__DF_LANG_AND_VISIBILITY_GUARD_READY__) return;
  window.__DF_LANG_AND_VISIBILITY_GUARD_READY__ = true;

  const FORBIDDEN_LANGS = new Set(["he", "iw", "syc", "ber", "zgh"]);
  window.dfAssertAllowedLanguage = function(code) {
    const norm = String(code || "en").trim().toLowerCase().split(/[-_]/)[0];
    if (!norm || FORBIDDEN_LANGS.has(norm)) return "en";
    return norm;
  };

  window.dfIsPageVisible = function() {
    return typeof document === "undefined" ? true : !document.hidden;
  };

  if (typeof document !== "undefined") {
    document.addEventListener("visibilitychange", function() {
      if (!document.hidden) {
        if (typeof window.dfEnforceStrictAsciiDigitsInAllViews === "function") {
          try { window.dfEnforceStrictAsciiDigitsInAllViews(); } catch (e) {}
        }
        if (typeof window.dfTriggerUISync === "function") {
          try { window.dfTriggerUISync(); } catch (e) {}
        }
      }
    });
  }
})();

/* === Deep Focus M09/M14/M19 Security Sanitizer, Schema Self-Repair & Engine Bridge === */
(function() {
  if (typeof window === "undefined" || window.__DF_SECURITY_AND_SCHEMA_READY__) return;
  window.__DF_SECURITY_AND_SCHEMA_READY__ = true;

  window.dfEscapeHtml = function(str) {
    return String(str == null ? "" : str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  };

  window.dfSanitizeHtmlFragment = function(html) {
    const raw = String(html == null ? "" : html);
    return raw
      .replace(/<\/?(?:script|iframe|object|embed|base|meta|link)\b[^>]*>/gi, "")
      .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, "")
      .replace(/(href|src)\s*=\s*(["'])\s*javascript:[^"']*\2/gi, '$1=$2#$2');
  };

  window.dfSafeSetHtml = function(el, html) {
    if (!el) return;
    el.innerHTML = window.dfSanitizeHtmlFragment(html);
  };

  window.dfValidateAndRepairBootData = function() {
    let repaired = 0;
    try {
      if (typeof cfg !== "undefined" && cfg && typeof cfg === "object") {
        if (!Number.isFinite(Number(cfg.todayMins)) || Number(cfg.todayMins) < 0) { cfg.todayMins = 0; repaired++; }
        if (!Number.isFinite(Number(cfg.streak)) || Number(cfg.streak) < 0) { cfg.streak = 0; repaired++; }
        if (!Array.isArray(cfg.sessionHistory)) { cfg.sessionHistory = []; repaired++; }
      }
      if (typeof tasks !== "undefined" && Array.isArray(tasks)) {
        const seenIds = new Set();
        for (let i = tasks.length - 1; i >= 0; i--) {
          const t = tasks[i];
          if (!t || typeof t !== "object") { tasks.splice(i, 1); repaired++; continue; }
          if (!t.id) { t.id = "task_" + i + "_" + Date.now(); repaired++; }
          if (seenIds.has(t.id)) { t.id = t.id + "_" + i; repaired++; }
          seenIds.add(t.id);
        }
      }
    } catch (e) {
      if (window.__dfRecordError) window.__dfRecordError("schemaRepair", e);
    }
    return { repaired };
  };

  if (typeof document !== "undefined") {
    document.addEventListener("DOMContentLoaded", () => {
      window.dfValidateAndRepairBootData();
      if (!window.SpokenVocabEngine && typeof VocabAudioBankEngine !== "undefined") {
        window.SpokenVocabEngine = VocabAudioBankEngine;
      }
    }, { once: true });
  }
})();

/* === Deep Focus M06/M08 Event-Driven UI Sync & Non-Blocking Notify === */
(function() {
  if (typeof window === "undefined" || window.__DF_UI_SYNC_BUS_READY__) return;
  window.__DF_UI_SYNC_BUS_READY__ = true;
  const hooks = [];
  let syncTimer = null;
  window.dfRegisterUISyncHook = function(fn) {
    if (typeof fn === "function" && !hooks.includes(fn)) {
      hooks.push(fn);
      if (typeof document !== "undefined" && document.readyState !== "loading") {
        try { fn(); } catch (e) { if (window.__dfRecordError) window.__dfRecordError("uiHookInit", e); }
      }
    }
  };
  window.dfTriggerUISync = function() {
    if (typeof document === "undefined") return;
    if (syncTimer) clearTimeout(syncTimer);
    syncTimer = setTimeout(() => {
      syncTimer = null;
      for (let i = 0; i < hooks.length; i++) {
        try { hooks[i](); } catch (e) { if (window.__dfRecordError) window.__dfRecordError("uiHookSync", e); }
      }
    }, 120);
  };
  window.dfSafeNotify = function(msg) {
    const text = String(msg || "").trim();
    if (!text) return;
    if (typeof showToast === "function") { try { showToast(text); return; } catch (e) {} }
    if (typeof console !== "undefined" && console.info) console.info("[DF]", text);
  };
  if (typeof document !== "undefined") {
    document.addEventListener("DOMContentLoaded", window.dfTriggerUISync, { once: true });
    document.addEventListener("click", (ev) => {
      if (ev && ev.target && ev.target.closest && ev.target.closest("button, [role='tab'], .nav-btn, .tab-btn")) window.dfTriggerUISync();
    }, { passive: true });
    window.addEventListener("df:ui-sync", window.dfTriggerUISync);
  }
})();


