/* ========================================================
   DEEP FOCUS — DAILY STREAK & 5-MIN KICKSTART ENGINE (M188)
   ======================================================== */
const HabitFocusEngine = (function() {
  function getSafeStorage() {
    return typeof localStorage !== 'undefined' ? localStorage : {
      getItem: () => null,
      setItem: () => {}
    };
  }

  // One source of truth: cfg.streak is calculated from real v21 sessionHistory.
  function getStreakData() {
    const count = typeof cfg === 'object' && Number.isFinite(cfg.streak)
      ? Math.max(0, Math.floor(cfg.streak)) : 0;
    return { count, lastDate: typeof localDateISO === 'function' ? localDateISO() : '' };
  }

  // Compatibility API: never manufacture a second, unrelated streak counter.
  function recordSessionForStreak() {
    updateStreakUI();
    return getStreakData().count;
  }

  function updateStreakUI() {
    const badge = document.getElementById('df-streak-badge-count');
    if (badge) {
      badge.textContent = getStreakData().count;
    }
  }

  function injectStreakBadge() {
    if (document.getElementById('df-streak-badge')) return;
    const header = document.querySelector('.timer-display, #timerDisplay, [class*="timer" i] h2')?.parentElement;
    if (!header) return;

    const streak = getStreakData().count;
    const badge = document.createElement('div');
    badge.id = 'df-streak-badge';
    badge.className = 'inline-flex items-center gap-1.5 px-3 py-1 bg-amber-50 border border-amber-200/90 text-amber-900 rounded-full text-xs font-bold shadow-xs mx-auto mb-2';

    const fireSpan = document.createElement('span');
    fireSpan.className = 'text-sm';
    fireSpan.textContent = '🔥';

    const countSpan = document.createElement('span');
    countSpan.id = 'df-streak-badge-count';
    countSpan.style.fontVariantNumeric = 'lining-nums';
    countSpan.textContent = String(streak);

    const labelSpan = document.createElement('span');
    labelSpan.id = 'df-streak-label';
    labelSpan.className = 'text-amber-700 font-semibold';
    labelSpan.textContent = String(L().daysUnit || 'Days');

    badge.appendChild(fireSpan);
    badge.appendChild(countSpan);
    badge.appendChild(labelSpan);

    header.insertBefore(badge, header.firstChild);
  }

  function showKickstartPrompt() {
    const lang = (typeof cfg !== 'undefined' && cfg && cfg.lang) ? cfg.lang : 'en';
    const tr = (k, fb) => (typeof window.dfGetLocalizedText === 'function' ? window.dfGetLocalizedText(k, lang, fb) : fb);
    const modal = document.createElement('div');
    modal.id = 'df-kickstart-modal';
    modal.className = 'fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4';

    const box = document.createElement('div');
    box.className = 'bg-white rounded-3xl p-6 max-w-xs w-full shadow-2xl border border-slate-100 text-center animate-in fade-in';

    const iconDiv = document.createElement('div');
    iconDiv.className = 'w-12 h-12 bg-amber-100 text-amber-600 rounded-2xl flex items-center justify-center mx-auto text-2xl font-bold mb-3';
    iconDiv.textContent = '⚡';

    const titleH3 = document.createElement('h3');
    titleH3.className = 'font-bold text-slate-900 text-base mb-1';
    titleH3.setAttribute('data-i18n', 'kickstartResistanceBroken');
    titleH3.textContent = tr('kickstartResistanceBroken', 'Resistance Broken!');

    const descP = document.createElement('p');
    descP.className = 'text-xs text-slate-500 mb-5 leading-relaxed';
    descP.setAttribute('data-i18n', 'kickstartConqueredDesc');
    descP.textContent = tr('kickstartConqueredDesc', 'You conquered the hardest 5 minutes. Ready to dive into a full 25-minute focus flow?');

    const btnCol = document.createElement('div');
    btnCol.className = 'flex flex-col gap-2';

    const extendBtn = document.createElement('button');
    extendBtn.id = 'df-extend-25m';
    extendBtn.className = 'w-full py-3 bg-blue-600 hover:bg-blue-700 active:scale-98 text-white rounded-xl text-xs font-bold transition shadow-md';
    extendBtn.setAttribute('data-i18n', 'kickstartExtend25m');
    extendBtn.textContent = tr('kickstartExtend25m', '🚀 Yes, Deep Focus (25m)');

    const closeBtn = document.createElement('button');
    closeBtn.id = 'df-kickstart-close';
    closeBtn.className = 'w-full py-2.5 bg-slate-100 hover:bg-slate-200 active:scale-98 text-slate-600 rounded-xl text-xs font-semibold transition';
    closeBtn.setAttribute('data-i18n', 'kickstartTakeBreak');
    closeBtn.textContent = tr('kickstartTakeBreak', '☕ Take a Break');

    btnCol.appendChild(extendBtn);
    btnCol.appendChild(closeBtn);
    box.appendChild(iconDiv);
    box.appendChild(titleH3);
    box.appendChild(descP);
    box.appendChild(btnCol);
    modal.appendChild(box);
    document.body.appendChild(modal);

    extendBtn.onclick = () => {
      // Reuse the existing session engine, including its Cancel logic.
      if (!selectHomeQuickSession(25)) return;
      modal.remove();
      if (!timerRunning) toggleTimerPlay();
      if (window.triggerHaptic) window.triggerHaptic('start');
    };

    closeBtn.onclick = () => {
      modal.remove();
    };
  }

  return {
    getStreakData,
    recordSessionForStreak,
    injectStreakBadge,
    showKickstartPrompt
  };
})();

window.HabitFocusEngine = HabitFocusEngine;

