/* ========================================================
   DEEP FOCUS — ACOUSTIC COMPLETION TONES & SELECTOR (M185)
   ======================================================== */
const COMPLETION_TONES = {
  zen_bell: { name: 'Water Drop 🎐', nameKey: 'toneZenBell', desc: 'Gentle', descKey: 'toneDescGentle', freq: 587.33, decay: 2.8, level: 0.3 },
  tibetan_bowl: { name: 'Stream Ripple 🧘', nameKey: 'toneTibetanBowl', desc: 'Deep', descKey: 'toneDescDeep', freq: 432, decay: 3.5, level: 0.35 },
  woodblock: { name: 'Rain Tap 🪵', nameKey: 'toneWoodblock', desc: 'Crisp', descKey: 'toneDescCrisp', freq: 800, decay: 0.25, level: 0.4 },
  crystal: { name: 'Wind Rustle 🔔', nameKey: 'toneCrystalBell', desc: 'Clear', descKey: 'toneDescClear', freq: 1046.5, decay: 2.5, level: 0.35 },
  gong: { name: 'Distant Thunder ⛩️', nameKey: 'toneTempleGong', desc: 'Loud', descKey: 'toneDescLoud', freq: 220, decay: 4.0, level: 0.5 },
  vibrate: { name: 'Vibrate Only 📳', nameKey: 'toneVibrateOnly', desc: 'Silent', descKey: 'toneDescSilent', freq: 0, decay: 0, level: 0 }
};

let toneCtx = null;

function playCompletionTone(toneKey) {
  const key = toneKey || localStorage.getItem('df_end_tone') || 'zen_bell';
  const tone = COMPLETION_TONES[key] || COMPLETION_TONES.zen_bell;

  if (window.triggerHaptic) {
    window.triggerHaptic('complete');
  }

  if (tone.freq === 0) return; // وضع الاهتزاز الصامت

  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    if (!toneCtx) toneCtx = new AudioCtx();
    if (toneCtx.state === 'suspended') toneCtx.resume();
    const ctx = toneCtx;

    const osc = (globalThis.__dfNoopOsc ? globalThis.__dfNoopOsc() : { type:"sine", frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){}}, detune:{value:0,setValueAtTime(){}}, connect(d){return d||this;}, disconnect(){}, start(){}, stop(){} });
    const gain = ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(tone.freq, ctx.currentTime);
    if (key === 'gong') {
      osc.frequency.exponentialRampToValueAtTime(tone.freq * 0.75, ctx.currentTime + tone.decay);
    } else {
      osc.frequency.exponentialRampToValueAtTime(tone.freq * 0.95, ctx.currentTime + tone.decay);
    }

    gain.gain.setValueAtTime(tone.level, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + tone.decay);

    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.onended = () => {
      try { osc.disconnect(); } catch (_) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", _); }
      try { gain.disconnect(); } catch (_) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", _); }
    };

    osc.start();
    osc.stop(ctx.currentTime + tone.decay);
  } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
}

window.playCompletionTone = playCompletionTone;

// بناء بطاقة اختيار النغمة داخل واجهة أصوات الطبيعة
function injectTonePickerUI() {
  if (document.getElementById('df-tone-picker-card')) return;
  const natureContainer = document.querySelector('#view-nature, [data-view="nature"], .nature-container') || document.querySelector('.sound-card')?.parentElement;
  if (!natureContainer) return;

  const lang = (typeof cfg !== 'undefined' && cfg && cfg.lang) ? cfg.lang : 'en';
  const tr = (k, fb) => (typeof window.dfGetLocalizedText === 'function' ? window.dfGetLocalizedText(k, lang, fb) : fb);
  const currentTone = localStorage.getItem('df_end_tone') || 'zen_bell';

  const card = document.createElement('div');
  card.id = 'df-tone-picker-card';
  card.className = 'p-4 bg-white/95 backdrop-blur rounded-2xl border border-slate-200/80 shadow-sm mb-4';

  const topRow = document.createElement('div');
  topRow.className = 'flex items-center justify-between mb-3';

  const leftRow = document.createElement('div');
  leftRow.className = 'flex items-center gap-2';
  const bellSpan = document.createElement('span');
  bellSpan.className = 'text-base';
  bellSpan.textContent = '🔔';
  const titleH3 = document.createElement('h3');
  titleH3.className = 'font-bold text-slate-800 text-sm';
  titleH3.setAttribute('data-i18n', 'focusEndChimeTitle');
  titleH3.textContent = tr('focusEndChimeTitle', 'Focus End Chime');
  leftRow.appendChild(bellSpan);
  leftRow.appendChild(titleH3);

  const badgeSpan = document.createElement('span');
  badgeSpan.className = 'text-[11px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full border border-blue-100';
  badgeSpan.setAttribute('data-i18n', 'zeroMusicBadge');
  badgeSpan.textContent = tr('zeroMusicBadge', 'Zero-Music');

  topRow.appendChild(leftRow);
  topRow.appendChild(badgeSpan);

  const gridDiv = document.createElement('div');
  gridDiv.className = 'grid grid-cols-2 gap-2 text-xs';

  Object.entries(COMPLETION_TONES).forEach(([id, t]) => {
    const btn = document.createElement('button');
    btn.dataset.toneId = id;
    btn.className = 'tone-btn flex items-center justify-between p-2.5 rounded-xl border ' +
      (id === currentTone
        ? 'border-blue-500 bg-blue-50/80 font-bold text-blue-900'
        : 'border-slate-200 bg-slate-50/60 text-slate-700') +
      ' hover:bg-slate-100 transition active:scale-98';
    const nameSpan = document.createElement('span');
    nameSpan.setAttribute('data-i18n', t.nameKey);
    nameSpan.textContent = tr(t.nameKey, t.name);
    const descSpan = document.createElement('span');
    descSpan.className = 'text-[10px] text-slate-400 font-medium';
    descSpan.setAttribute('data-i18n', t.descKey);
    descSpan.textContent = tr(t.descKey, t.desc);
    btn.appendChild(nameSpan);
    btn.appendChild(descSpan);

    btn.onclick = () => {
      const toneId = btn.dataset.toneId;
      localStorage.setItem('df_end_tone', toneId);
      card.querySelectorAll('.tone-btn').forEach(b => {
        b.className = 'tone-btn flex items-center justify-between p-2.5 rounded-xl border border-slate-200 bg-slate-50/60 text-slate-700 hover:bg-slate-100 transition active:scale-98';
      });
      btn.className = 'tone-btn flex items-center justify-between p-2.5 rounded-xl border border-blue-500 bg-blue-50/80 font-bold text-blue-900 transition active:scale-98';
      playCompletionTone(toneId); // سماع معاينة فورية
    };
    gridDiv.appendChild(btn);
  });

  card.appendChild(topRow);
  card.appendChild(gridDiv);

  natureContainer.insertBefore(card, natureContainer.firstChild);
}

document.addEventListener('DOMContentLoaded', () => {
  injectTonePickerUI();
  // إعادة المحاولة عند التبديل بين الأقسام
  const observer = new MutationObserver(injectTonePickerUI);
  observer.observe(document.body, { childList: true, subtree: true });
});


/* ========================================================
   DEEP FOCUS — LUXURY HAPTIC & PEACEFUL CHIME ENGINE (M184)
   ======================================================== */
function triggerHaptic(type) {
  if (!navigator.vibrate) return;
  try {
    if (type === 'click') ((navigator.vibrate && (!navigator.userActivation || navigator.userActivation.hasBeenActive)) ? navigator.vibrate(10) : false);
    else if (type === 'step') ((navigator.vibrate && (!navigator.userActivation || navigator.userActivation.hasBeenActive)) ? navigator.vibrate(16) : false);
    else if (type === 'start') ((navigator.vibrate && (!navigator.userActivation || navigator.userActivation.hasBeenActive)) ? navigator.vibrate(28) : false);
    else if (type === 'complete') ((navigator.vibrate && (!navigator.userActivation || navigator.userActivation.hasBeenActive)) ? navigator.vibrate([35, 60, 35, 60, 80]) : false);
  } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
}

function playPeacefulChime() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    if (ctx.state === 'suspended') ctx.resume();

    // نغمة جرس التأمل الهادئة (528 Hz Harmonic)
    const osc = (globalThis.__dfNoopOsc ? globalThis.__dfNoopOsc() : { type:"sine", frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){}}, detune:{value:0,setValueAtTime(){}}, connect(d){return d||this;}, disconnect(){}, start(){}, stop(){} });
    const gain = ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(528, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(264, ctx.currentTime + 3.2);

    gain.gain.setValueAtTime(0.35, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 3.2);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 3.2);
    triggerHaptic('complete');
  } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
}

window.triggerHaptic = triggerHaptic;
window.playPeacefulChime = playPeacefulChime;

