function localDateISO(date = new Date()) {
  return [
    String(date.getFullYear()),
    String(date.getMonth() + 1).padStart(2, '0'),
    String(date.getDate()).padStart(2, '0')
  ].join('-');
}
let todayISO = localDateISO();
function escapeHtmlText(s) {
  if (s == null) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

let cfg = loadFortressData('zen_fortress_cfg_v21', {
  lang: 'en', domain: 'study', focusMin: 25, shortMin: 5, longMin: 15,
  todayMins: 0, sessions: 0, streak: 0, water: 0, sets: 0, pagesRead: 0
});

function computeActualStreak(history, now = new Date()) {
  const days = new Set(
    (Array.isArray(history) ? history : [])
      .filter(e => e && /^\d{4}-\d{2}-\d{2}$/.test(e.date) && Number(e.minutes) > 0)
      .map(e => e.date)
  );
  const day = new Date(now);
  day.setHours(12, 0, 0, 0);
  if (!days.has(localDateISO(day))) day.setDate(day.getDate() - 1);
  let count = 0;
  while (count < 10000 && days.has(localDateISO(day))) {
    count += 1;
    day.setDate(day.getDate() - 1);
  }
  return count;
}

function syncDailyRollover() {
  const current = localDateISO();
  const entries = Array.isArray(cfg.sessionHistory) ? cfg.sessionHistory : null;
  // An unavailable optional analytics module must never erase cached values.
  if (entries) {
    const next = JSON.parse(JSON.stringify(cfg));
    if (next.metricsDate && next.metricsDate !== current) {
      next.todayMins = entries
        .filter(e => e && e.date === current && Number.isFinite(Number(e.minutes)))
        .reduce((total, e) => total + Math.max(0, Number(e.minutes)), 0);
      next.water = 0;
      next.sets = 0;
      next.pagesRead = 0;
      next.quickFocusRemainderSec = 0;
    }
    next.metricsDate = current;
    next.streak = computeActualStreak(next.sessionHistory);
    if (JSON.stringify(next) !== JSON.stringify(cfg)) {
      try {
        if (window.DF22Integration) {
          const before = window.DF22Integration.getSnapshot();
          if (window.DF22Integration.write(before, {...before,cfg:next}) !== true)
            throw new Error('ROLLOVER_SAVE_NOT_VERIFIED');
        } else {
          if (saveFortressData('zen_fortress_cfg_v21', next) !== true)
            throw new Error('ROLLOVER_SAVE_NOT_VERIFIED');
          cfg = next;
        }
      } catch (_) {
        showToast((typeof L === 'function' && L().saveFailed) || 'Could not save daily progress. Retry.');
        return false;
      }
    }
  }
  // Date controls advance only after the daily snapshot has been acknowledged.
  if (todayISO !== current) {
    const previousDate = todayISO;
    todayISO = current;
    const taskDateInput = document.getElementById('inpTaskDate');
    if (taskDateInput && taskDateInput.value === previousDate) taskDateInput.value = current;
    if (typeof selectedCalDate !== 'undefined' && selectedCalDate === previousDate) {
      selectedCalDate = current;
      calYear = new Date().getFullYear();
      calMonth = new Date().getMonth();
    }
  }
  return true;
}

/* ============================================================================
   UNIVERSAL THOUSAND-LANGUAGE ARCHITECTURE — INFINITE LOCALE REGISTRY (v22+)
   - Dynamically loads, synthesizes, and maps 1,000+ world languages & regional dialects
   - Strictly excludes Hebrew, Syriac, and Amazigh across all registries and UI
   - Enforces dynamic RTL for right-to-left languages and LTR for all others
   - Guarantees Western standard digits (0123456789) across every language
   ============================================================================ */
const DF_EXCLUDED_LOCALE_CODES = new Set([
  'he', 'iw', 'heb', 'hbo', 'yi', 'yid', 'jrb', 'jpr', 'lad',
  'syc', 'syr', 'aii', 'cld', 'tru', 'oar', 'sam', 'tmr', 'jpa', 'cpb',
  'ber', 'zgh', 'tzm', 'kab', 'shi', 'rif', 'tmh', 'taq', 'zen', 'gha', 'mzb', 'oua', 'sjs', 'siz', 'tjo', 'thv', 'thz', 'ttq', 'cnu', 'grr'
]);
const DF_EXCLUDED_SCRIPT_RE = /[\u0590-\u05FF\u0700-\u074F\u2D30-\u2D7F]/;

function dfIsExcludedLocale(code, meta) {
  if (!code || typeof code !== 'string') return true;
  const raw = code.toLowerCase().trim();
  if (!raw) return true;
  const parts = raw.split(/[-_]/);
  for (let i = 0; i < parts.length; i++) {
    if (DF_EXCLUDED_LOCALE_CODES.has(parts[i])) return true;
  }
  if (DF_EXCLUDED_LOCALE_CODES.has(raw)) return true;
  if (meta && typeof meta === 'object') {
    const labelBlob = `${meta.enName || ''} ${meta.nativeName || ''} ${meta.name || ''}`.toLowerCase();
    if (/hebrew|syriac|amazigh|tamazight|tifinagh|berber|aramaic|assyrian|chaldean|yiddish/.test(labelBlob)) return true;
    if (DF_EXCLUDED_SCRIPT_RE.test(labelBlob)) return true;
  }
  return false;
}
window.dfIsExcludedLocale = dfIsExcludedLocale;

const DF_RTL_BASE_CODES = new Set([
  'ar', 'fa', 'ur', 'ps', 'sd', 'ug', 'ckb', 'prs', 'dv', 'ks',
  'bal', 'bqi', 'glk', 'mzn', 'lrc', 'azb', 'pnb', 'khw', 'hno',
  'skr', 'haz', 'rhg', 'shu', 'ary', 'arz', 'apd', 'acm', 'acw',
  'acq', 'aeb', 'ajp', 'apc', 'ars', 'avl', 'ayh', 'ayl', 'ayn',
  'ayp', 'bbz', 'pga', 'sqr', 'ssh', 'abv', 'aec', 'afb', 'ags'
]);

function dfIsRtlLocale(code) {
  if (!code || typeof code !== 'string') return false;
  const clean = code.toLowerCase().trim();
  if (DF_RTL_BASE_CODES.has(clean)) return true;
  const parts = clean.split(/[-_]/);
  if (DF_RTL_BASE_CODES.has(parts[0])) return true;
  if (parts.includes('arab') || parts.includes('thaa') || parts.includes('nkoo') || parts.includes('adlm') || parts.includes('rohg')) return true;
  const cat = Array.isArray(LANG_CATALOG) ? LANG_CATALOG.find(x => x && x.code && x.code.toLowerCase() === clean) : null;
  if (cat && cat.dir === 'rtl') return true;
  return false;
}
window.dfIsRtlLocale = dfIsRtlLocale;

