function confirmSensitiveAction(kind) {
  const base = (cfg && cfg.lang) ? String(cfg.lang).toLowerCase().split(/[-_]/)[0] : 'en';
  const copy = CONFIRMATION_TEXT[cfg.lang] || CONFIRMATION_TEXT[base] || CONFIRMATION_TEXT.en;
  const index = {task:0, note:1, restore:2}[kind];
  if (!Number.isInteger(index)) return false;
  return window.confirm(copy[index]);
}

function openLanguageModal() {
  dfSyncInfiniteLocaleRegistry();
  document.getElementById('inpLangCountrySearch').value = '';
  renderLanguageList();
  document.getElementById('langModal').classList.add('open');
}

function renderLanguageList() {
  dfSyncInfiniteLocaleRegistry();
  const q = (document.getElementById('inpLangCountrySearch').value || '').toLowerCase().trim();
  const box = document.getElementById('langListScrollBox');
  if (!box) return;
  box.replaceChildren();

  LANG_CATALOG.filter(l => {
    if (!l || dfIsExcludedLocale(l.code, l)) return false;
    if (!q) return true;
    return (l.enName || '').toLowerCase().includes(q) ||
           (l.nativeName || '').toLowerCase().includes(q) ||
           (l.iso || '').toLowerCase().includes(q) ||
           (l.code || '').toLowerCase().includes(q) ||
           (l.countries || '').toLowerCase().includes(q);
  }).forEach(l => {
    const row = document.createElement('button');
    row.type = 'button';
    const isActive = cfg.lang === l.code;
    row.className = `lang-row-btn ${isActive ? 'active' : ''}`;
    row.setAttribute('aria-pressed', String(isActive));
    row.onclick = () => applyLanguage(l.code);
    const icon = document.createElement('div');
    icon.className = 'lang-code-monogram';
    icon.textContent = toWest(l.iso);
    const names = document.createElement('div');
    names.className = 'lang-names-col';
    const english = document.createElement('div');
    english.className = 'lang-en-title';
    english.textContent = toWest(l.enName);
    const native = document.createElement('div');
    native.className = 'lang-native-sub';
    native.textContent = toWest(l.nativeName);
    names.appendChild(english);
    names.appendChild(native);
    const mark = document.createElement('span');
    mark.style.cssText = 'font-size:0.75rem;font-weight:900;color:var(--primary);';
    mark.textContent = isActive ? '✓' : '';
    row.appendChild(icon);
    row.appendChild(names);
    row.appendChild(mark);
    box.appendChild(row);
  });
}

function localizeStarterPreviews(target) {
  // IDs 1..4 and 1..3 are the stable v21 demonstration records.
  // A user-edited demonstration record is no longer replaced by translation.
  const packs = Object.values(DICT);
  if (Array.isArray(target.sampleTasks)) {
    tasksList.forEach(record => {
      if (!record || record.isStarter !== true || !Number.isSafeInteger(record.id)) return;
      const index = record.id - 1;
      if (index < 0 || index >= target.sampleTasks.length) return;
      const unchanged = packs.some(pack => Array.isArray(pack.sampleTasks) &&
        typeof pack.sampleTasks[index] === 'string' && record.title === toWest(pack.sampleTasks[index]));
      if (unchanged) record.title = toWest(target.sampleTasks[index]);
    });
  }
  if (Array.isArray(target.sampleNotes)) {
    notesList.forEach(record => {
      if (!record || record.isStarter !== true || !Number.isSafeInteger(record.id)) return;
      const index = record.id - 1;
      if (index < 0 || index >= target.sampleNotes.length) return;
      const unchanged = packs.some(pack => {
        const sample = Array.isArray(pack.sampleNotes) && pack.sampleNotes[index];
        return sample && record.title === toWest(sample.t) && record.body === toWest(sample.b);
      });
      if (unchanged) {
        record.title = toWest(target.sampleNotes[index].t);
        record.body = toWest(target.sampleNotes[index].b);
      }
    });
  }
}

function applyLanguage(code) {
  dfSyncInfiniteLocaleRegistry();
  const rawInput = typeof code === 'string' ? code.toLowerCase().trim() : 'en';
  const safeInput = dfIsExcludedLocale(rawInput) ? 'en' : rawInput;
  const baseCode = safeInput.split(/[-_]/)[0] || 'en';
  const meta = LANG_CATALOG.find(x => x.code.toLowerCase() === safeInput && !dfIsExcludedLocale(x.code, x))
    || LANG_CATALOG.find(x => x.code.toLowerCase() === baseCode && !dfIsExcludedLocale(x.code, x))
    || LANG_CATALOG.find(x => x.code === 'en');
  const previousLang = cfg.lang;
  cfg.lang = meta.code;
  window.DF_CURRENT_LOCALE = meta.code;
  try {
    saveFortressData('zen_fortress_cfg_v21', cfg);
  } catch (error) {
    cfg.lang = previousLang; // An unacknowledged write must not change the active locale.
    throw error;
  }
  const d = L();
  const isRtl = dfIsRtlLocale(meta.code);
  const resolvedDir = isRtl ? 'rtl' : 'ltr';
  meta.dir = resolvedDir;

  const root = document.getElementById('htmlRoot') || document.documentElement;
  if (root) {
    root.setAttribute('lang', meta.code);
    root.setAttribute('dir', resolvedDir);
    root.dir = resolvedDir;
  }
  if (document.body) {
    document.body.setAttribute('dir', resolvedDir);
    document.body.style.direction = resolvedDir;
    document.body.style.textAlign = isRtl ? 'right' : 'left';
  }
  if (typeof window.dfApplyRtlA11yStyles === 'function') {
    window.dfApplyRtlA11yStyles();
  }

  const isoEl = document.getElementById('currentLangIso');
  if (isoEl) isoEl.textContent = toWest(meta.iso);
  const languageLabel = document.getElementById('currentLangLabel');
  if (languageLabel) {
    languageLabel.textContent = toWest(`${meta.enName} • ${meta.nativeName}`);
    languageLabel.parentElement?.setAttribute('aria-label',
      toWest(`${meta.iso} ${meta.enName} • ${meta.nativeName}`));
  }
  const hdrMain = document.getElementById('hdrMainTitle');
  if (hdrMain) hdrMain.textContent = 'Deep Focus';
  const hdrSub = document.getElementById('hdrSubTitle');
  if (hdrSub) hdrSub.textContent = toWest(d.sub || dfGetLocalizedText('sub', meta.code, 'Zero-Cloud Academic & Athletic Sanctuary'));
  const tn = document.getElementById('navTrainingText');
  const trainingLabel = dfGetLocalizedText('navTrainingText', meta.code,
    window.DF22Locale?.translations?.[baseCode]?.quickTraining
    || (typeof quickText === 'function' ? quickText('trainingTitle') : 'Quick training'));
  if (tn) tn.textContent = toWest(trainingLabel);
  document.getElementById('navTraining')?.setAttribute('aria-label', toWest(trainingLabel));
  if (typeof refreshTimerSettings === 'function') refreshTimerSettings();

  document.querySelectorAll('[data-i18n]').forEach(el => {
    // Never replace an editable value or arbitrary user-generated content.
    if (el.isContentEditable || /^(INPUT|TEXTAREA)$/i.test(el.tagName || '')) return;
    // Replacing textContent on a container would wipe its icon/title/duration children;
    // such containers localise through their own labelled child elements.
    if (el.children.length > 0) return;
    const k = el.getAttribute('data-i18n');
    const value = dfGetLocalizedText(k, meta.code, el.textContent);
    if (value && value !== k && el.textContent !== value) el.textContent = toWest(value);
  });

  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const k = el.getAttribute('data-i18n-placeholder');
    const value = dfGetLocalizedText(k, meta.code, el.getAttribute('placeholder') || '');
    if (value && value !== k) el.setAttribute('placeholder', toWest(value));
  });

  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const k = el.getAttribute('data-i18n-title');
    const value = dfGetLocalizedText(k, meta.code, el.getAttribute('title') || '');
    if (value && value !== k) el.setAttribute('title', toWest(value));
  });

  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    const k = el.getAttribute('data-i18n-aria');
    const value = dfGetLocalizedText(k, meta.code, el.getAttribute('aria-label') || '');
    if (value && value !== k) el.setAttribute('aria-label', toWest(value));
  });

  localizeStarterPreviews(d);

  renderAnalyticsBars();

  // One failing renderer must never abort the rest of the language switch
  // (modal close, quick-training text and premium locale layer run after these).
  // Thunks: renderNotesStack/renderSoundsStudio live in scripts loaded after app.js,
  // so at first boot they do not exist yet (a ReferenceError here used to abort the
  // whole app.js boot sequence). A late re-apply on window load covers those screens.
  [() => syncHeaderMetrics(), () => updateTimerDisplay(), () => renderTasksList(),
   () => renderCalendar(), () => renderNotesStack(), () => renderSoundsStudio(),
   () => updateSyllabusCalc()].forEach(step => {
    try { step(); } catch (error) {
      if (!(error instanceof ReferenceError)) console.error('applyLanguage step failed:', error);
    }
  });
  closeModal('langModal');
  if (typeof quickL10n === 'function') quickL10n();
  // Premium labels may also be created by re-rendered screens; refresh last.
  if (window.DF22Locale?.apply) window.DF22Locale.apply(document, baseCode);
  if (window.DF22Integration?.refreshLocale) window.DF22Integration.refreshLocale();
  // Chrome created outside the dictionaries (studio pill, tools drawer) follows the UI language.
  try {
    const arUi = baseCode === 'ar';
    const setText = (id, ar, en) => { const n = document.getElementById(id); if (n) n.textContent = arUi ? ar : en; };
    const setAria = (id, ar, en) => { const n = document.getElementById(id); if (n) n.setAttribute('aria-label', arUi ? ar : en); };
    setText('zenStudioTriggerLabel', '✨ الاستوديوهات', '✨ Studios');
    setAria('zenStudioTriggerPill', 'فتح لوحة الاستوديوهات والأدوات', 'Open studios and tools panel');
    setText('sovereignCalmToolsLabel', '⚙️ أدوات الاستوديو والصيانة المتقدمة', '⚙️ Advanced studio & maintenance tools');
    setAria('sovereignCalmToolsToggle', 'فتح أو إغلاق أدوات الاستوديو والصيانة', 'Open or close studio and maintenance tools');
    setText('toggleTwilightBtn', '🌙 وضع السكينة الليلي (Eye Comfort)', '🌙 Night calm mode (Eye Comfort)');
    setAria('toggleTwilightBtn', 'تفعيل أو إيقاف وضع السكينة الليلي لحماية العين', 'Toggle night calm mode to protect your eyes');
  } catch (_) { /* cosmetic */ }
  // Keep the secondary hot-swap engine on the same language so its DOM sweeps never
  // overwrite the language the user picked.
  try {
    const hot = window.UniversalI18nHotSwap;
    if (hot && typeof hot.applyLanguage === 'function' && hot.currentLang !== baseCode) hot.applyLanguage(baseCode);
  } catch (_) { /* optional engine */ }
  try {
    if (window.ZenNative && typeof window.ZenNative.setNativeLocale === 'function')
      window.ZenNative.setNativeLocale(meta.code);
  } catch (_) { /* Web preview has no native bridge. */ }
}

/* ========================================================
   3. CLOUD BACKUP, SOVEREIGN SAF ENVELOPE & EASY SHARE
   ======================================================== */
function computeSovereignChecksumHex(str) {
  const input = String(str || '');
  let h1 = 0x811c9dc5 >>> 0;
  let h2 = 0x9e3779b9 >>> 0;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 ^= ch;
    h1 = Math.imul(h1, 0x01000193) >>> 0;
    h2 ^= (ch + (i & 0xff));
    h2 = Math.imul(h2, 0x85ebca6b) >>> 0;
  }
  return 'SOV21-' + h1.toString(16).padStart(8, '0') + '-' + h2.toString(16).padStart(8, '0') + '-' + input.length.toString(16);
}

function collectFlashcardDecksForBackup() {
  try {
    if (window.VocabAudioBankEngine && typeof window.VocabAudioBankEngine.getVocabList === 'function') {
      const list = window.VocabAudioBankEngine.getVocabList();
      if (Array.isArray(list)) return list;
    }
    const rawVocab = localStorage.getItem('df_vocab_bank') || localStorage.getItem('df_cards_v1');
    if (rawVocab) {
      const parsed = JSON.parse(rawVocab);
      if (Array.isArray(parsed)) return parsed;
    }
  } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
  return [];
}

function collectStudyStreaksForBackup() {
  return {
    streak: Number(cfg && cfg.streak) || 0,
    todayMins: Number(cfg && cfg.todayMins) || 0,
    sessions: Number(cfg && cfg.sessions) || 0,
    lastDate: String((cfg && cfg.lastDate) || todayISO),
    sessionHistory: Array.isArray(cfg && cfg.sessionHistory) ? cfg.sessionHistory : []
  };
}

function buildSovereignBackupEnvelopeObject() {
  const flashcardDecks = collectFlashcardDecksForBackup();
  const studyStreaks = collectStudyStreaksForBackup();
  const bundleObj = {
    cfg,
    tasksList,
    notesList,
    flashcardDecks,
    studyStreaks,
    v: 21
  };
  const bundle = JSON.stringify(bundleObj);
  const sig = computeHash(bundle);
  const checksum = computeSovereignChecksumHex(bundle);
  return {
    envelope: 'DEEP_FOCUS_SOVEREIGN_VAULT_V21',
    v: 21,
    createdAt: new Date().toISOString(),
    alg: 'FNV1A-DUAL-CHECKSUM',
    sig,
    checksum,
    bundle
  };
}

function generateEncryptedBackupCode() {
  const env = buildSovereignBackupEnvelopeObject();
  const encoded = btoa(unescape(encodeURIComponent(JSON.stringify({
    bundle: env.bundle,
    sig: env.sig,
    checksum: env.checksum,
    envelope: env.envelope,
    v: 21
  }))));
  return "ZEN21::" + encoded;
}

function validateImportedBackup(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw) || raw.v !== 21) return null;
  if (!raw.cfg || typeof raw.cfg !== 'object' || Array.isArray(raw.cfg)) return null;
  if (!Array.isArray(raw.tasksList) || !Array.isArray(raw.notesList)) return null;
  if (raw.tasksList.length > 10000 || raw.notesList.length > 10000) return null;
  // New imports must use the original numeric v21 ID type, never string coercion.
  const safeRecordId = id => typeof id === 'number' && Number.isSafeInteger(id) && id >= 0;
  const uniqueRecordIds = records => {
    const seen = new Set();
    return records.every(record => {
      if (seen.has(record.id)) return false;
      seen.add(record.id);
      return true;
    });
  };
  const okTask = x => x && typeof x === 'object' && !Array.isArray(x)
    && safeRecordId(x.id)
    && typeof x.title === 'string' && x.title.length <= 20000
    && typeof x.done === 'boolean';
  const okNote = x => x && typeof x === 'object' && !Array.isArray(x)
    && safeRecordId(x.id)
    && typeof x.title === 'string' && x.title.length <= 20000
    && typeof x.body === 'string' && x.body.length <= 500000;
  if (!raw.tasksList.every(okTask) || !raw.notesList.every(okNote)
      || !uniqueRecordIds(raw.tasksList) || !uniqueRecordIds(raw.notesList)) return null;
  const candidateCfg = {...cfg, ...raw.cfg};
  if (!LANG_CATALOG.some(l => l.code === candidateCfg.lang)) candidateCfg.lang = 'en';
  for (const key of ['todayMins', 'sessions', 'streak', 'water']) {
    const n = Number(candidateCfg[key]);
    if (!Number.isFinite(n) || n < 0 || n > 100000000) return null;
    candidateCfg[key] = n;
  }
  if (candidateCfg.sessionHistory !== undefined
      && (!Array.isArray(candidateCfg.sessionHistory) || candidateCfg.sessionHistory.length > 100000)) return null;

  let validFlashcards = null;
  if (Array.isArray(raw.flashcardDecks) && raw.flashcardDecks.length <= 25000) {
    validFlashcards = raw.flashcardDecks
      .filter(c => c && typeof c === 'object' && !Array.isArray(c))
      .map((c, idx) => ({
        id: String(c.id || ('v_restored_' + idx)),
        term: String(c.term || c.front || '').slice(0, 5000),
        translation: String(c.translation || c.back || '').slice(0, 5000),
        notes: String(c.notes || '').slice(0, 5000),
        color: String(c.color || 'purple'),
        stability: Number(c.stability || c.s) || 1.0,
        s: Number(c.s || c.stability) || 1.0,
        difficulty: Number(c.difficulty || c.d) || 5.0,
        d: Number(c.d || c.difficulty) || 5.0,
        interval: Number(c.interval || c.ivl) || 1,
        ivl: Number(c.ivl || c.interval) || 1,
        reviewCount: Number(c.reviewCount || c.reps || c.reviews) || 0,
        reps: Number(c.reps || c.reviewCount || c.reviews) || 0,
        needsReview: Boolean(c.needsReview),
        lastReviewed: String(c.lastReviewed || todayISO)
      }));
  }

  return {
    cfg: candidateCfg,
    tasksList: raw.tasksList,
    notesList: raw.notesList,
    flashcardDecks: validFlashcards,
    studyStreaks: raw.studyStreaks && typeof raw.studyStreaks === 'object' ? raw.studyStreaks : null
  };
}

function verifyAndRestoreBackupCode(codeStr) {
  try {
    const clean = String(codeStr || '').trim();
    if (clean.length > 14000000 || !clean) throw new Error('Invalid backup size');
    let decoded = null;
    if (clean.startsWith('{')) {
      decoded = JSON.parse(clean);
    } else {
      const rawB64 = clean.startsWith('ZEN21::') ? clean.slice(7).trim() : clean;
      decoded = JSON.parse(decodeURIComponent(escape(atob(rawB64))));
    }
    if (!decoded || typeof decoded.bundle !== 'string' || !decoded.sig
        || computeHash(decoded.bundle) !== decoded.sig) throw new Error('Integrity check failed');
    if (decoded.checksum && computeSovereignChecksumHex(decoded.bundle) !== decoded.checksum) {
      throw new Error('Sovereign checksum mismatch');
    }
    const verified = validateImportedBackup(JSON.parse(decoded.bundle));
    if (!verified) throw new Error('Invalid backup schema');
    // Validation must complete before writes. Never replace a user's work silently.
    if (!confirmSensitiveAction('restore')) return false;
    // Build and verify every storage packet before replacing any saved record.
    // If a write fails (e.g. storage quota), roll back all six original keys.
    if (window.DF22Integration) {
      // The live app shares the same crash-recoverable transaction as Notes/Tasks.
      const before = window.DF22Integration.getSnapshot();
      if (window.DF22Integration.write(before, verified) !== true) throw new Error('RESTORE_NOT_VERIFIED');
    } else {
      const imports = [
        ['zen_fortress_cfg_v21', verified.cfg],
        ['zen_fortress_tasks_v21', verified.tasksList],
        ['zen_fortress_notes_v21', verified.notesList]
      ];
      const updates = [];
      for (const [key, value] of imports) {
        const payload = JSON.stringify(value);
        updates.push([key, JSON.stringify({payload, sig:computeHash(payload), ts:Date.now()})]);
      }
      const previous = new Map();
      for (const [key] of updates) {
        previous.set(key, localStorage.getItem(key));
        previous.set(key + '_mirror', localStorage.getItem(key + '_mirror'));
      }
      try {
        for (const [key, packet] of updates) {
          localStorage.setItem(key, packet);
          localStorage.setItem(key + '_mirror', packet);
        }
        for (const [key, packet] of updates) {
          if (localStorage.getItem(key) !== packet || localStorage.getItem(key + '_mirror') !== packet) {
            throw new Error('Storage verification failed');
          }
        }
        if (typeof window !== 'undefined' && window.ZenNative && (!window.DF22Preflight || !window.DF22Preflight.nativeAcknowledge(localStorage)))
          throw new Error('NATIVE_DURABLE_ACK_FAILED');
      } catch (storageError) {
        for (const [key, oldValue] of previous) {
          try {
            if (oldValue === null) localStorage.removeItem(key);
            else localStorage.setItem(key, oldValue);
          } catch (rollbackError) {
            console.error('Backup rollback failed:', key, rollbackError);
          }
        }
        throw storageError;
      }
      cfg = verified.cfg;
      tasksList = verified.tasksList;
      notesList = verified.notesList;
    }
    if (Array.isArray(verified.flashcardDecks)) {
      try {
        localStorage.setItem('df_vocab_bank', JSON.stringify(verified.flashcardDecks));
        localStorage.setItem('df_cards_v1', JSON.stringify(verified.flashcardDecks));
      } catch (_) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", _); }
    }
    if (Array.isArray(verified.cfg.sessionHistory)) {
      try {
        localStorage.setItem('df_session_history_v1', JSON.stringify(verified.cfg.sessionHistory));
      } catch (_) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", _); }
    }
    syncDailyRollover();
    applyLanguage(cfg.lang);
    closeModal('cloudBackupModal');
    showToast('✓ Backup restored');
    return true;
  } catch (e) {
    showToast('⚠️ Backup invalid — original data left unchanged');
    return false;
  }
}

function openCloudBackupModal() {
  document.getElementById('inpRestorePayload').value = '';
  document.getElementById('cloudBackupModal').classList.add('open');
  // Update display-only backup labels after the modal exists and before user action.
  // Never alter backup payload, consent, restore callbacks or storage here.
  window.DeepFocusAudioSettingsLocale?.bindBackupDialog({document, locale: cfg.lang});
}

async function syncToGoogleCloudNow() {
  const code = generateEncryptedBackupCode();
  if (window.ZenNative && typeof window.ZenNative.syncBackupToGoogleEmailOrDrive === 'function') {
    window.ZenNative.syncBackupToGoogleEmailOrDrive(code);
  } else if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
    try {
      await navigator.clipboard.writeText(code);
      showToast("Backup copied — save privately; NOT encrypted");
    } catch (_) {
      showToast("⚠️ Backup copy failed — use Export Backup File");
    }
  } else {
    showToast("⚠️ Clipboard unavailable — use Export Backup File");
  }
}

function downloadEncryptedBackupFile() {
  const code = generateEncryptedBackupCode();
  if (window.ZenNative && window.ZenNative.exportBackupToFile) {
    try {
      window.ZenNative.exportBackupToFile(code);
      return; // Android reports success only after the user actually saves the file.
    } catch (error) {
      showToast('⚠️ Could not open Save As; use Share Backup');
      return;
    }
  }
  // Browser-only fallback; Android WebView should use ACTION_CREATE_DOCUMENT.
  const blob = new Blob([code], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `deep-focus-backup-${todayISO}.zenbackup`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 60000);
  showToast("💾 Backup exported — NOT encrypted");
}

function restoreFromEncryptedCode() {
  const val = document.getElementById('inpRestorePayload').value;
  if (!val) return showToast("⚠️ Paste backup code first");
  verifyAndRestoreBackupCode(val);
}

function restoreFromFileInput(ev) {
  const file = ev.target.files[0];
  if (!file) return;
  if (file.size > 8 * 1024 * 1024) return showToast('⚠️ Backup file is too large');
  const reader = new FileReader();
  reader.onload = (e) => verifyAndRestoreBackupCode(e.target.result);
  reader.readAsText(file);
}

async function shareAppWithFriends() {
  const msg = toWest(`🌿 Deep Focus — My Progress Today: ${cfg.todayMins} active mins (${cfg.sessions} sessions completed, 🔥 ${cfg.streak} days streak)!`);
  if (window.ZenNative && window.ZenNative.shareAppInvite) {
    window.ZenNative.shareAppInvite(msg);
  } else {
    try {
      if (!navigator.clipboard || typeof navigator.clipboard.writeText !== 'function') throw Error('CLIPBOARD_UNAVAILABLE');
      await navigator.clipboard.writeText(msg);
      showToast("📤 Copied to Clipboard!");
      return true;
    } catch (_) {
      showToast(typeof nsLabel === 'function' ? nsLabel(34) : '⚠️');
      return false;
    }
  }
}

