    phase = "EXHALATION_PACING";
    phaseTitle = "Vagus Nerve Deceleration";
    instruction = "Inhale slowly for 4 seconds, exhale softly for 8 seconds to lower heart rate";
    inhale = 4;
    exhale = 8;
