// ============================================================================
// MISSION #327: Phone Pickup & Movement Distraction Alert (v4.5.7)
// ============================================================================
function dfGetDistractionMovementMetrics(sensorReading, sessionState, options) {
  const reading = sensorReading || {};
  const state = sessionState || {};
  const opts = options || {};

  const isRunning = Boolean(state.isRunning);
  const now = typeof opts.currentTime === "number" ? opts.currentTime : Date.now();
  const lastAlertTime = typeof state.lastAlertTime === "number" ? state.lastAlertTime : 0;
  const currentPickups = typeof state.pickupCount === "number" && state.pickupCount >= 0 ? Math.floor(state.pickupCount) : 0;

  const pitch = Math.abs(typeof reading.pitch === "number" ? reading.pitch : 0);
  const roll = Math.abs(typeof reading.roll === "number" ? reading.roll : 0);
  const accel = typeof reading.accelDelta === "number" ? reading.accelDelta : 0;

  const sensitivity = (opts.alertSensitivity || "NORMAL").toUpperCase();
  const pitchThreshold = sensitivity === "HIGH" ? 18 : (sensitivity === "LOW" ? 35 : 25);
  const rollThreshold = sensitivity === "HIGH" ? 20 : (sensitivity === "LOW" ? 40 : 30);
  const accelThreshold = sensitivity === "HIGH" ? 1.5 : (sensitivity === "LOW" ? 3.0 : 2.0);

  const isMoving = isRunning && (pitch > pitchThreshold || roll > rollThreshold) && (accel > accelThreshold);
  const isDebounced = lastAlertTime === 0 || (now - lastAlertTime) >= 5000;

  let triggered = false;
  let newPickups = currentPickups;

  if (isMoving && isDebounced) {
    triggered = true;
    newPickups++;
    state.lastAlertTime = now;
    state.pickupCount = newPickups;
  }

  const purity = Math.max(0, 100 - (newPickups * 5));

  return {
    versionCode: 147,
    versionName: "4.5.7",
    isPickupDetected: triggered,
    pickupCount: newPickups,
    focusPurityPercent: purity,
    shouldTriggerAlertChime: triggered && opts.audioChimeEnabled !== false,
    reminderAdvice: triggered
      ? "Unconscious phone pickup detected: place phone back on desk and return to focus"
      : "Device resting stable on desk",
    westernDigits: true,
    timestamp: now
  };
}

if (typeof window !== "undefined") {
  window.dfGetDistractionMovementMetrics = dfGetDistractionMovementMetrics;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfGetDistractionMovementMetrics = dfGetDistractionMovementMetrics;
}

// ============================================================================
// MISSION #328: Focus Quality & Friction Tagging Rating (v4.5.8)
// ============================================================================
function dfRateSessionFocusQuality(ratingData, historyList) {
  const d = ratingData || {};
  const rawRating = typeof d.rating === "number" ? Math.floor(d.rating) : 5;
  const rating = Math.min(5, Math.max(1, rawRating));

  const allowedTags = [
    "MENTAL_FATIGUE",
    "EXTERNAL_NOISE",
    "DIFFICULT_MATERIAL",
    "PHONE_TEMPTATION",
    "HUNGER_THIRST",
    "POOR_SLEEP",
    "PERFECT_FLOW"
  ];

  const inputTags = Array.isArray(d.frictionTags) ? d.frictionTags : [];
  const validTags = inputTags.filter(t => allowedTags.includes(String(t).toUpperCase()));
  if (rating === 5 && validTags.length === 0) {
    validTags.push("PERFECT_FLOW");
  }

  const starSymbols = ["☆☆☆☆☆", "★☆☆☆☆", "★★☆☆☆", "★★★☆☆", "★★★★☆", "★★★★★"];
  const starsVisual = starSymbols[rating];

  let category = "DEEP_FLOW";
  if (rating <= 2) category = "HIGH_FRICTION";
  else if (rating === 3) category = "MODERATE_FOCUS";
  else if (rating === 4) category = "STRONG_FOCUS";

  const history = Array.isArray(historyList) ? historyList : [];
  let totalRating = rating;
  let count = 1;

  for (const item of history) {
    if (item && typeof item.rating === "number" && item.rating >= 1 && item.rating <= 5) {
      totalRating += item.rating;
      count++;
    }
  }

  const avgRating = Math.round((totalRating / count) * 10) / 10;

  return {
    versionCode: 148,
    versionName: "4.5.8",
    rating: rating,
    starsVisual: starsVisual,
    frictionTags: validTags,
    qualityCategory: category,
    averageRating: avgRating,
    formattedAverage: avgRating + " / 5.0",
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfRateSessionFocusQuality = dfRateSessionFocusQuality;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfRateSessionFocusQuality = dfRateSessionFocusQuality;
}

// ============================================================================
// MISSION #329: Chronotype Peak Productivity Hours Analytics (v4.5.9)
// ============================================================================
function dfAnalyzeChronotypePeakHours(historyList) {
  const history = Array.isArray(historyList) ? historyList : [];
  const hourBins = new Array(24).fill(0);
  let totalSessions = 0;

  for (const item of history) {
    if (!item) continue;
    const ts = typeof item.timestamp === "number" ? item.timestamp : Date.now();
    const date = new Date(ts);
    const hour = date.getHours();
    const duration = typeof item.durationMinutes === "number" && item.durationMinutes > 0 ? item.durationMinutes : 25;
    const rating = typeof item.rating === "number" && item.rating >= 1 && item.rating <= 5 ? item.rating : 3;

    hourBins[hour] += duration * (rating / 3.0);
    totalSessions++;
  }

  const indexed = hourBins.map((score, h) => ({ hour: h, score: score }));
  indexed.sort((a, b) => b.score - a.score);

  const top3 = indexed.slice(0, 3).map(x => x.hour);
  const topHour = top3[0] || 10;

  let morningScore = 0;
  let afternoonScore = 0;
  let nightScore = 0;

  for (let h = 0; h < 24; h++) {
    if (h >= 5 && h < 11) morningScore += hourBins[h];
    else if (h >= 11 && h < 18) afternoonScore += hourBins[h];
    else nightScore += hourBins[h];
  }

  let chronotype = "BEAR";
  let chronotypeLabel = "Steady Daytime Focus (Bear)";
  let recWindow = "10:00 - 13:00";

  if (morningScore > afternoonScore && morningScore > nightScore) {
    chronotype = "LARK";
    chronotypeLabel = "Early Morning Peak (Lark)";
    recWindow = "07:00 - 10:30";
  } else if (nightScore > morningScore && nightScore > afternoonScore) {
    chronotype = "OWL";
    chronotypeLabel = "Late Evening Focus (Night Owl)";
    recWindow = "20:00 - 23:30";
  }

  const pad = (n) => (n < 10 ? "0" + n : "" + n);
  const nextHour = (topHour + 1) % 24;
  const topFormatted = pad(topHour) + ":00 - " + pad(nextHour) + ":00";

  return {
    versionCode: 149,
    versionName: "4.5.9",
    chronotype: chronotype,
    chronotypeLabel: chronotypeLabel,
    topPeakHour: topHour,
    topPeakWindowFormatted: topFormatted,
    top3PeakHours: top3,
    totalAnalyzedSessions: totalSessions,
    recommendedDeepWorkWindow: recWindow,
    westernDigits: true,
    timestamp: Date.now()
  };
}

if (typeof window !== "undefined") {
  window.dfAnalyzeChronotypePeakHours = dfAnalyzeChronotypePeakHours;
}
if (typeof globalThis !== "undefined") {
  globalThis.dfAnalyzeChronotypePeakHours = dfAnalyzeChronotypePeakHours;
}

// ============================================================================
// MISSION #330: Box Breathing & 4-7-8 Pre-Session Pacer (v4.6.0)
// ============================================================================
function dfGetBoxBreathingPacerMetrics(elapsedSeconds, patternType, totalCyclesCount) {
  const elapsed = typeof elapsedSeconds === "number" && elapsedSeconds >= 0 ? Math.floor(elapsedSeconds) : 0;
  const pattern = (patternType || "BOX_4_4_4_4").toUpperCase();
  const maxCycles = typeof totalCyclesCount === "number" && totalCyclesCount > 0 ? Math.floor(totalCyclesCount) : 4;

  let intervals = [
    { name: "INHALE", duration: 4, cue: "Inhale Slowly Through Nose" },
    { name: "HOLD_IN", duration: 4, cue: "Hold Breath Gently" },
    { name: "EXHALE", duration: 4, cue: "Smooth Exhale Through Mouth" },
    { name: "HOLD_OUT", duration: 4, cue: "Rest Empty" }
  ];

  if (pattern === "RELAX_4_7_8") {
    intervals = [
      { name: "INHALE", duration: 4, cue: "Deep Inhale Through Nose" },
      { name: "HOLD_IN", duration: 7, cue: "Hold Breath with Relaxation" },
      { name: "EXHALE", duration: 8, cue: "Whoosh Exhale Through Mouth" }
    ];
  }

  const cycleDuration = intervals.reduce((acc, x) => acc + x.duration, 0);
  const totalDuration = cycleDuration * maxCycles;

  if (elapsed >= totalDuration) {
    return {
      versionCode: 150,
      versionName: "4.6.0",
      pattern: pattern,
      currentPhase: "COMPLETE",
      phaseCue: "Centering Complete: Enter Flow State",
      phaseProgressPercent: 100,
      currentCycle: maxCycles,
      totalCycles: maxCycles,
      isSessionReady: true,
      westernDigits: true,
      timestamp: Date.now()
    };
  }

  const currentCycleIndex = Math.min(maxCycles, Math.floor(elapsed / cycleDuration) + 1);
  const cycleOffset = elapsed % cycleDuration;

  let accumulated = 0;
  let activePhase = intervals[0];
  let phaseElapsed = 0;

  for (const interval of intervals) {
    if (cycleOffset < accumulated + interval.duration) {
      activePhase = interval;
      phaseElapsed = cycleOffset - accumulated;
      break;
    }
    accumulated += interval.duration;
  }

  const phaseRemaining = activePhase.duration - phaseElapsed;
  const phaseProgress = Math.min(100, Math.round((phaseElapsed / activePhase.duration) * 100));

  return {
    versionCode: 150,
    versionName: "4.6.0",
    pattern: pattern,
    currentPhase: activePhase.name,
    phaseCue: activePhase.cue,
    phaseSecondsRemaining: phaseRemaining,
    phaseProgressPercent: phaseProgress,
    currentCycle: currentCycleIndex,
    totalCycles: maxCycles,
    isSessionReady: false,
    westernDigits: true,
    timestamp: Date.now()
  };
}

