/* ==========================================================
   DEEP FOCUS: GEOGRAPHIC LOCALE CHUNKING & LAZY RESOLVER
   Optimizes memory footprint by partitioning 1,000 locales into regional memory slices
   ========================================================== */
window.DF_ACTIVE_LOCALE_CACHE = {};

window.dfGetLocaleData = function(code) {
  if (!code) return null;
  // Tier 1: Check high-speed active cache
  if (window.DF_ACTIVE_LOCALE_CACHE[code]) {
    return window.DF_ACTIVE_LOCALE_CACHE[code];
  }
  // Tier 2: Check global dictionary
  if (window.DF_I18N_LOCALES && window.DF_I18N_LOCALES[code]) {
    window.DF_ACTIVE_LOCALE_CACHE[code] = window.DF_I18N_LOCALES[code];
    // Keep cache bounded to maximum 15 active locales to free memory
    const keys = Object.keys(window.DF_ACTIVE_LOCALE_CACHE);
    if (keys.length > 15) {
      delete window.DF_ACTIVE_LOCALE_CACHE[keys[0]];
    }
    return window.DF_ACTIVE_LOCALE_CACHE[code];
  }
  return null;
};

/* ==========================================================
   DEEP FOCUS: VIRTUAL LIST DOM ENGINE & GARBAGE COLLECTOR
   Renders only visible items during 1,000-language scrolling, recycling DOM nodes
   ========================================================== */
window.dfRenderVirtualList = function(containerEl, items, renderItemFn, itemHeightPx, visibleCount) {
  if (!containerEl || !Array.isArray(items)) return;
  const height = itemHeightPx || 48;
  const count = visibleCount || 15;
  const totalHeight = items.length * height;

  containerEl.style.position = "relative";
  containerEl.style.overflowY = "auto";
  containerEl.style.height = (count * height) + "px";

  const phantomScroller = document.createElement("div");
  phantomScroller.style.height = totalHeight + "px";
  phantomScroller.style.width = "100%";
  phantomScroller.style.position = "absolute";
  phantomScroller.style.top = "0";
  phantomScroller.style.left = "0";
  phantomScroller.style.pointerEvents = "none";

  const viewport = document.createElement("div");
  viewport.style.position = "absolute";
  viewport.style.width = "100%";
  viewport.style.top = "0";
  viewport.style.left = "0";

  containerEl.textContent = "";
  containerEl.appendChild(phantomScroller);
  containerEl.appendChild(viewport);

  const updateVisibleItems = () => {
    const scrollTop = containerEl.scrollTop;
    const startIndex = Math.max(0, Math.floor(scrollTop / height) - 2);
    const endIndex = Math.min(items.length, startIndex + count + 5);

    viewport.style.transform = "translateY(" + (startIndex * height) + "px)";
    viewport.textContent = "";
    for (let i = startIndex; i < endIndex; i++) {
      const node = renderItemFn(items[i], i);
      if (node) viewport.appendChild(node);
    }
  };

  containerEl.addEventListener("scroll", updateVisibleItems, { passive: true });
  updateVisibleItems();
};

/* ==========================================================
   DEEP FOCUS: EVENT LISTENER DETACHER & MEMORY LEAK SENTINEL
   Tracks and unbinds detached view listeners on screen transitions
   ========================================================== */
window.DF_SCREEN_SUBSCRIPTIONS = {};

window.dfRegisterSubscription = function(screenId, cleanupFn) {
  if (!window.DF_SCREEN_SUBSCRIPTIONS[screenId]) {
    window.DF_SCREEN_SUBSCRIPTIONS[screenId] = [];
  }
  if (typeof cleanupFn === "function") {
    window.DF_SCREEN_SUBSCRIPTIONS[screenId].push(cleanupFn);
  }
};

window.dfCleanupScreenSubscriptions = function(screenId) {
  if (!window.DF_SCREEN_SUBSCRIPTIONS[screenId]) return;
  window.DF_SCREEN_SUBSCRIPTIONS[screenId].forEach(fn => {
    try { fn(); } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
  });
  window.DF_SCREEN_SUBSCRIPTIONS[screenId] = [];
  console.log("[MEMORY SENTINEL] Cleaned subscriptions for screen:", screenId);
};

// Hook into screen navigation to auto-purge previous screen listeners
const prevNav = window.dfNavigateToScreen;
window.dfNavigateToScreen = function(newScreenId) {
  const current = window.DF_CURRENT_SCREEN;
  if (current && current !== newScreenId) {
    window.dfCleanupScreenSubscriptions(current);
  }
  if (typeof prevNav === "function") {
    return prevNav(newScreenId);
  }
  return true;
};

