/* ==========================================================
   DEEP FOCUS: PARAMETRIC NATURE SOUND CUSTOMIZER ENGINE
   Real-time mathematical filter tuning (Intensity, Tone, Cutoff)
   ========================================================== */
window.DF_SOUND_PARAMS = {
  intensity: 0.5, // 0.1 (gentle) to 1.0 (deep)
  tone: "soft"    // "soft", "balanced", "crisp"
};

window.dfSetSoundParameters = function(intensity, tone) {
  if (typeof intensity === "number") {
    window.DF_SOUND_PARAMS.intensity = Math.max(0.1, Math.min(1.0, intensity));
  }
  if (tone && ["soft", "balanced", "crisp"].includes(tone)) {
    window.DF_SOUND_PARAMS.tone = tone;
  }

  // Live-update active filter nodes if audio is currently playing
  if (window.DF_ACTIVE_AUDIO_NODES) {
    const filterNode = window.DF_ACTIVE_AUDIO_NODES.find(n => n instanceof BiquadFilterNode);
    if (filterNode && filterNode.frequency) {
      const baseFreq = window.DF_SOUND_PARAMS.tone === "soft" ? 450 : (window.DF_SOUND_PARAMS.tone === "crisp" ? 1200 : 750);
      filterNode.frequency.setTargetAtTime(baseFreq * window.DF_SOUND_PARAMS.intensity, 0, 0.2);
    }
  }
  if (window.dfSafeSetStorage) window.dfSafeSetStorage("df_sound_params", window.DF_SOUND_PARAMS);
  console.log("[DSP] Sound parameters updated:", window.DF_SOUND_PARAMS);
};

if (typeof window !== "undefined" && window.dfSafeGetStorage) {
  const saved = window.dfSafeGetStorage("df_sound_params", null);
  if (saved) window.DF_SOUND_PARAMS = saved;
}

/* ==========================================================
   DEEP FOCUS: ACOUSTIC EAR-SAFETY LIMITER & ANTI-CLIPPING GUARD
   Studio-grade dynamic compression preventing listener fatigue
   ========================================================== */
window.DF_MASTER_COMPRESSOR = null;

window.dfGetSafeMasterDestination = function(ctx) {
  if (!ctx) return null;
  if (!window.DF_MASTER_COMPRESSOR) {
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.setValueAtTime(-18, ctx.currentTime); // Soft knee starts at -18dB
    comp.knee.setValueAtTime(12, ctx.currentTime);
    comp.ratio.setValueAtTime(12, ctx.currentTime);        // Brickwall limiter ratio
    comp.attack.setValueAtTime(0.003, ctx.currentTime);    // 3ms instant peak catch
    comp.release.setValueAtTime(0.25, ctx.currentTime);
    comp.connect(ctx.destination);
    window.DF_MASTER_COMPRESSOR = comp;
    console.log("[DSP SECURITY] Acoustic Ear-Safety Master Limiter active.");
  }
  return window.DF_MASTER_COMPRESSOR;
};

/* ==========================================================
   DEEP FOCUS: SMOOTH CROSSFADE & END-OF-SESSION FADE-OUT SENTINEL
   Eliminates jarring sound cuts with 2.5s exponential audio crossfade
   ========================================================== */
window.dfCrossfadeToSound = async function(newSoundType, fadeDurationSec) {
  const duration = fadeDurationSec || 2.0;
  const ctx = window.dfGetSafeAudioContext ? window.dfGetSafeAudioContext() : null;
  
  if (window.DF_ACTIVE_AUDIO_NODES && window.DF_ACTIVE_AUDIO_NODES.length > 0 && ctx) {
    const gainNode = window.DF_ACTIVE_AUDIO_NODES.find(n => n instanceof GainNode);
    if (gainNode && gainNode.gain) {
      gainNode.gain.cancelScheduledValues(ctx.currentTime);
      gainNode.gain.setValueAtTime(gainNode.gain.value, ctx.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
      setTimeout(() => {
        window.dfStopAllSounds();
        if (newSoundType && newSoundType !== "none") window.dfPlayNatureSound(newSoundType);
      }, duration * 1000);
      return;
    }
  }
  if (newSoundType && newSoundType !== "none") window.dfPlayNatureSound(newSoundType);
};

/* ==========================================================
   DEEP FOCUS: UNIVERSAL ANKI & CSV FLASHCARD IMPORTER/EXPORTER
   Parses Tab, Comma, and Semicolon delimited study sets seamlessly
   ========================================================== */
window.dfParseCardsFromText = function(rawText) {
  if (!rawText || typeof rawText !== "string") return [];
  const lines = rawText.split(/\r?\n/).filter(line => line.trim().length > 0);
  const parsedCards = [];

  lines.forEach((line, index) => {
    // Auto-detect delimiter: Tab (Anki) vs Semicolon vs Comma
    let parts = line.split("\t");
    if (parts.length < 2) parts = line.split(";");
    if (parts.length < 2) parts = line.split(",");

    if (parts.length >= 2) {
      const front = parts[0].trim();
      const back = parts[1].trim();
      const tags = parts[2] ? parts[2].split(" ").map(t => t.trim()).filter(Boolean) : [];

      if (front && back) {
        parsedCards.push({
          id: "card_" + Date.now() + "_" + index,
          front: front,
          back: back,
          tags: tags,
          reps: 0,
          interval: 0,
          easeFactor: 2.5,
          dueDate: new Date().toISOString().split("T")[0]
        });
      }
    }
  });
  console.log("[SRS IMPORTER] Successfully parsed " + parsedCards.length + " cards from text payload.");
  return parsedCards;
};

window.dfExportDeckToTSV = function(cardsList) {
  if (!Array.isArray(cardsList)) return "";
  return cardsList.map(c => {
    const tags = Array.isArray(c.tags) ? c.tags.join(" ") : "";
    return (c.front || "") + "\t" + (c.back || "") + (tags ? "\t" + tags : "");
  }).join("\n");
};

/* ==========================================================
   DEEP FOCUS: HIERARCHICAL SUB-DECKS & TAG TAXONOMY ENGINE
   Standard double-colon namespace hierarchy (Parent::Child::Topic)
   ========================================================== */
window.dfParseDeckHierarchy = function(deckName) {
  if (!deckName) return { root: "Default", path: ["Default"], depth: 1 };
  const parts = deckName.split("::").map(p => p.trim()).filter(Boolean);
  return {
    root: parts[0] || "Default",
    leaf: parts[parts.length - 1],
    path: parts,
    depth: parts.length
  };
};

window.dfFilterCardsByTag = function(cardsList, targetTag) {
  if (!Array.isArray(cardsList) || !targetTag) return cardsList;
  const tagLower = targetTag.toLowerCase();
  return cardsList.filter(c => {
    return Array.isArray(c.tags) && c.tags.some(t => t.toLowerCase() === tagLower);
  });
};

window.dfExtractAllDeckTags = function(cardsList) {
  if (!Array.isArray(cardsList)) return [];
  const tagSet = new Set();
  cardsList.forEach(c => {
    if (Array.isArray(c.tags)) c.tags.forEach(t => tagSet.add(t));
  });
  return Array.from(tagSet).sort();
};

/* ==========================================================
   DEEP FOCUS: EXAM READINESS & EBBINGHAUS FORGETTING FORECASTER
   Computes required daily study velocity based on exam target date
   ========================================================== */
window.dfComputeExamForecast = function(cardsList, examDateISO) {
  if (!Array.isArray(cardsList) || !examDateISO) {
    return { daysRemaining: 0, dailyPaceRequired: 0, readinessScore: 100 };
  }

  const now = new Date().getTime();
  const examTime = new Date(examDateISO).getTime();
  const daysRemaining = Math.max(1, Math.ceil((examTime - now) / 86400000));

  let unmasteredCards = 0;
  cardsList.forEach(c => {
    if ((c.interval || 0) < 21 || (c.reps || 0) < 3) {
      unmasteredCards++;
    }
  });

  const dailyPace = Math.ceil(unmasteredCards / daysRemaining);
  const total = Math.max(1, cardsList.length);
  const readiness = Math.round(((total - unmasteredCards) / total) * 100);

  return {
    daysRemaining: daysRemaining,
    unmasteredCards: unmasteredCards,
    dailyPaceRequired: dailyPace,
    readinessScore: readiness,
    recommendation: dailyPace <= 15 ? "ON_TRACK" : (dailyPace <= 35 ? "ACCELERATE" : "INTENSIVE_REVISION")
  };
};

/* ==========================================================
   DEEP FOCUS: PURE MATHEMATICAL 365-DAY STUDY HEATMAP (SVG)
   Zero external libraries - Generates 52-week activity grid in < 3ms
   ========================================================== */
window.dfGenerateYearlyHeatmapSVG = function(sessionsList) {
  const sessions = Array.isArray(sessionsList) ? sessionsList : [];
  const dayMap = {};
  sessions.forEach(s => {
    const d = s.date || (s.timestamp ? s.timestamp.split("T")[0] : null);
    if (d) dayMap[d] = (dayMap[d] || 0) + (s.durationMinutes || Math.floor((s.durationSeconds || 0) / 60));
  });

  const width = 720, height = 110, cellSize = 11, gap = 3;
  let svg = '<svg viewBox="0 0 ' + width + ' ' + height + '" width="100%" height="110" xmlns="http://www.w3.org/2000/svg">';
  
  const now = new Date();
  const oneYearAgo = new Date(now.getTime() - (52 * 7 * 86400000));
  
  const colors = ["#1e293b", "#0e4429", "#006d32", "#26a641", "#39d353"];

  for (let w = 0; w < 52; w++) {
    for (let d = 0; d < 7; d++) {
      const currentCellDate = new Date(oneYearAgo.getTime() + ((w * 7 + d) * 86400000));
      const dateKey = currentCellDate.toISOString().split("T")[0];
      const minutes = dayMap[dateKey] || 0;

      let colorIdx = 0;
      if (minutes >= 90) colorIdx = 4;
      else if (minutes >= 45) colorIdx = 3;
      else if (minutes >= 20) colorIdx = 2;
      else if (minutes > 0) colorIdx = 1;

      const x = w * (cellSize + gap) + 10;
      const y = d * (cellSize + gap) + 10;
      svg += '<rect x="' + x + '" y="' + y + '" width="' + cellSize + '" height="' + cellSize + '" rx="2" fill="' + colors[colorIdx] + '"><title>' + dateKey + ': ' + minutes + 'm</title></rect>';
    }
  }
  svg += '</svg>';
  return svg;
};

/* ==========================================================
   DEEP FOCUS: CHRONOTYPE & PEAK FOCUS HOURS DETECTOR
   Discovers peak mental productivity windows across 24 hourly buckets
   ========================================================== */
window.dfDetectPeakFocusHours = function(sessionsList) {
  const sessions = Array.isArray(sessionsList) ? sessionsList : [];
  const hourBuckets = new Array(24).fill(0);

  sessions.forEach(s => {
    if (s.timestamp) {
      const hour = new Date(s.timestamp).getHours();
      hourBuckets[hour] += (s.durationMinutes || Math.floor((s.durationSeconds || 0) / 60));
    }
  });

  let maxMinutes = 0;
  let peakHour = 9; // Default 09:00 AM
  hourBuckets.forEach((mins, h) => {
    if (mins > maxMinutes) {
      maxMinutes = mins;
      peakHour = h;
    }
  });

  const formatHour = (h) => (h < 10 ? "0" + h : "" + h) + ":00";
  const peakWindow = formatHour(peakHour) + " - " + formatHour((peakHour + 2) % 24);

  let chronotype = "BALANCED";
  if (peakHour >= 5 && peakHour < 12) chronotype = "EARLY_BIRD";
  else if (peakHour >= 12 && peakHour < 18) chronotype = "AFTERNOON_FOCUSED";
  else if (peakHour >= 18 || peakHour < 5) chronotype = "NIGHT_OWL";

  return {
    peakHour: peakHour,
    peakWindow: peakWindow,
    chronotype: chronotype,
    peakMinutesTotal: maxMinutes,
    hourlyDistribution: hourBuckets
  };
};

/* ==========================================================
   DEEP FOCUS: DAILY FOCUS GOAL & STREAK PROTECTION BUFFER
   Tracks daily target completion with rest-day streak shielding
   ========================================================== */
window.dfGetDailyGoalProgress = function(targetMinutes, todaySessionsList) {
  const target = targetMinutes || (window.dfSafeGetStorage ? window.dfSafeGetStorage("df_daily_goal_mins", 120) : 120);
  const todayStr = new Date().toISOString().split("T")[0];
  const sessions = Array.isArray(todaySessionsList) ? todaySessionsList : [];

  let todayMins = 0;
  sessions.forEach(s => {
    const d = s.date || (s.timestamp ? s.timestamp.split("T")[0] : null);
    if (d === todayStr) {
      todayMins += (s.durationMinutes || Math.floor((s.durationSeconds || 0) / 60));
    }
  });

  const percentage = Math.min(100, Math.round((todayMins / target) * 100));
  return {
    targetMinutes: target,
    completedMinutes: todayMins,
    remainingMinutes: Math.max(0, target - todayMins),
    percentage: percentage,
    isGoalAchieved: todayMins >= target
  };
};

window.dfSetDailyTargetMinutes = function(mins) {
  const target = Math.max(15, Math.min(720, mins));
  if (window.dfSafeSetStorage) window.dfSafeSetStorage("df_daily_goal_mins", target);
  return target;
};

/* ==========================================================
   DEEP FOCUS: ZERO-XSS INPUT SANITIZER & HTML SHIELD
   Safely neutralizes malicious scripts and malformed tags during paste
   ========================================================== */
window.dfSanitizeHTML = function(dirtyInput) {
  if (!dirtyInput || typeof dirtyInput !== "string") return "";
  
  // Replace dangerous HTML entities
  const map = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#x27;",
    "/": "&#x2F;"
  };
  const sanitized = dirtyInput.replace(/[&<>"'/]/g, (s) => map[s]);
  
  // Strip dangerous javascript: or data: pseudo protocols
  return sanitized.replace(/javascript:/gi, "").replace(/data:/gi, "");
};

window.dfSafeSetCardText = function(element, rawText) {
  if (!element) return;
  // Always use textContent to prevent arbitrary script execution
  element.textContent = rawText || "";
};

/* ==========================================================
   DEEP FOCUS: DUAL-SLOT REDUNDANCY & CRASH-PROOF STORAGE SHIELD
   Guarantees zero data loss even if phone battery dies mid-write
   ========================================================== */
window.dfAtomicSave = function(key, dataObj) {
  if (typeof localStorage === "undefined") return false;
  try {
    const serialized = JSON.stringify(dataObj);
    // Write to Primary slot
    localStorage.setItem(key + "_primary", serialized);
    // Write mirror to Backup slot
    localStorage.setItem(key + "_backup", serialized);
    return true;
  } catch (e) {
    console.error("[STORAGE] Atomic write failed:", e.message);
    return false;
  }
};

window.dfAtomicLoad = function(key, defaultVal) {
  if (typeof localStorage === "undefined") return defaultVal;
  
  // Try loading Primary slot
  try {
    const prim = localStorage.getItem(key + "_primary");
    if (prim !== null) return JSON.parse(prim);
  } catch (e) {
    console.warn("[STORAGE] Primary slot corrupted, recovering from backup...");
  }

  // Fallback to Backup slot
  try {
    const backup = localStorage.getItem(key + "_backup");
    if (backup !== null) {
      const recovered = JSON.parse(backup);
      // Self-heal primary slot
      localStorage.setItem(key + "_primary", backup);
      console.log("[STORAGE] Successfully recovered data from backup slot.");
      return recovered;
    }
  } catch (e) {
    console.error("[STORAGE] Both slots unparseable. Returning default.");
  }

  return defaultVal;
};

/* ==========================================================
   DEEP FOCUS: ANOMALOUS DATA FILTER & TIME-TAMPERING SENTINEL
   Purges invalid session lengths caused by manual clock manipulation
   ========================================================== */
window.dfFilterAnomalousSessions = function(sessionsList) {
  if (!Array.isArray(sessionsList)) return [];
  const maxSessionSeconds = 12 * 3600; // 12 hours max continuous session
  const validSessions = [];

  sessionsList.forEach(s => {
    const sec = s.durationSeconds || (s.durationMinutes ? s.durationMinutes * 60 : 0);
    // Discard negative durations or absurdly large values
    if (sec > 0 && sec <= maxSessionSeconds && s.timestamp) {
      validSessions.push(s);
    }
  });

  return validSessions;
};

