/* ==========================================================
   DEEP FOCUS: ARIA LIVE REGIONS & SCREEN READER ANNOUNCER
   TalkBack accessibility bridge announcing timer milestones
   ========================================================== */
window.dfAnnounceToScreenReader = function(message) {
  if (typeof document === "undefined") return;
  let liveRegion = document.getElementById("df-aria-live-announcer");
  if (!liveRegion) {
    liveRegion = document.createElement("div");
    liveRegion.id = "df-aria-live-announcer";
    liveRegion.setAttribute("aria-live", "polite");
    liveRegion.setAttribute("aria-atomic", "true");
    liveRegion.style.position = "absolute";
    liveRegion.style.width = "1px";
    liveRegion.style.height = "1px";
    liveRegion.style.overflow = "hidden";
    liveRegion.style.clip = "rect(1px, 1px, 1px, 1px)";
    document.body.appendChild(liveRegion);
  }
  liveRegion.textContent = message;
};

/* ==========================================================
   DEEP FOCUS: OFFLINE QR PAYLOAD COMPRESSION ENGINE
   Mathematical text compression enabling offline camera card transfers
   ========================================================== */
window.dfCompressDeckPayload = function(cardsList) {
  if (!Array.isArray(cardsList) || cardsList.length === 0) return "";
  // Compact representation: array of [front, back, tagsString]
  const compactArray = cardsList.map(c => [
    c.front || "",
    c.back || "",
    Array.isArray(c.tags) ? c.tags.join(",") : ""
  ]);
  const rawJSON = JSON.stringify(compactArray);
  // Base64 safe URI component encoding
  try {
    return btoa(encodeURIComponent(rawJSON));
  } catch (e) {
    return "";
  }
};

window.dfDecompressDeckPayload = function(compressedBase64) {
  if (!compressedBase64 || typeof compressedBase64 !== "string") return [];
  try {
    const rawJSON = decodeURIComponent(atob(compressedBase64));
    const compactArray = JSON.parse(rawJSON);
    return compactArray.map((item, idx) => ({
      id: "shared_" + Date.now() + "_" + idx,
      front: item[0] || "",
      back: item[1] || "",
      tags: item[2] ? item[2].split(",").map(t => t.trim()).filter(Boolean) : [],
      reps: 0,
      interval: 0,
      easeFactor: 2.5,
      dueDate: new Date().toISOString().split("T")[0]
    }));
  } catch (e) {
    console.error("[DEEP FOCUS P2P] Decompression failed:", e.message);
    return [];
  }
};

/* ==========================================================
   DEEP FOCUS: CONFLICT-FREE CARD MERGING & DEDUPLICATION ENGINE
   Seamlessly integrates peer cards without overwriting existing study progress
   ========================================================== */
window.dfMergeCardsConflictFree = function(existingCards, incomingCards) {
  const existing = Array.isArray(existingCards) ? [...existingCards] : [];
  const incoming = Array.isArray(incomingCards) ? incomingCards : [];

  const existingMap = new Set();
  existing.forEach(c => {
    const key = (c.front || "").trim().toLowerCase();
    if (key) existingMap.add(key);
  });

  let addedCount = 0;
  let skippedDuplicates = 0;

  incoming.forEach(card => {
    const key = (card.front || "").trim().toLowerCase();
    if (key && !existingMap.has(key)) {
      existing.push(card);
      existingMap.add(key);
      addedCount++;
    } else {
      skippedDuplicates++;
    }
  });

  console.log("[P2P MERGE] Merged " + addedCount + " new cards, skipped " + skippedDuplicates + " duplicates.");
  return {
    mergedList: existing,
    addedCount: addedCount,
    skippedDuplicates: skippedDuplicates
  };
};

/* ==========================================================
   DEEP FOCUS: DEEP-LINK OFFLINE PAYLOAD RESOLVER
   Detects URL import hashes and facilitates zero-cloud deck imports
   ========================================================== */
window.dfCheckUrlImportPayload = function() {
  if (typeof window === "undefined" || !window.location) return;
  const hash = window.location.hash || "";
  if (hash.startsWith("#import=")) {
    const payload = hash.substring(8);
    if (payload && window.dfDecompressDeckPayload) {
      const cards = window.dfDecompressDeckPayload(payload);
      if (cards.length > 0) {
        console.log("[DEEP LINK] Incoming study payload detected:", cards.length, "cards.");
        return cards;
      }
    }
  }
  return null;
};

if (typeof window !== "undefined") {
  window.dfCheckUrlImportPayload();
}

