/* ==========================================================
   DEEP FOCUS: CONSTANT-TIME STRING COMPARISON SENTINEL (SECTOR 6 LAUNCH)
   Eliminates side-channel microsecond timing attacks on PIN verification
   ========================================================== */
window.dfConstantTimeEquals = function(a, b) {
  if (typeof a !== "string" || typeof b !== "string") return false;
  let mismatch = a.length === b.length ? 0 : 1;
  const len = Math.min(a.length, b.length);

  // Bitwise XOR loop always evaluates every single character identically
  for (let i = 0; i < len; i++) {
    mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return mismatch === 0;
};

/* ==========================================================
   DEEP FOCUS: ANTI-PROTOTYPE POLLUTION JSON SANITIZER
   Neutralizes malicious __proto__ and constructor keys during deck ingestion
   ========================================================== */
window.dfDeepSanitizeObject = function(obj) {
  if (obj === null || typeof obj !== "object") return obj;
  if (Array.isArray(obj)) return obj.map(window.dfDeepSanitizeObject);

  const clean = Object.create(null); // Pure dictionary without prototype chain
  for (const key of Object.keys(obj)) {
    if (key === "__proto__" || key === "constructor" || key === "prototype") {
      console.warn("[SECURITY BLOCKED] Prototype pollution vector neutralized:", key);
      continue;
    }
    clean[key] = window.dfDeepSanitizeObject(obj[key]);
  }
  return clean;
};

/* ==========================================================
   DEEP FOCUS: HARDWARE-BOUND PBKDF2 KEY DERIVATION (v56.1.0)
   100,000 cryptographic hash rounds with device-unique entropy salt
   ========================================================== */
window.dfDeriveHardwareBoundKey = async function(userPin) {
  if (typeof crypto === "undefined" || !crypto.subtle) return null;
  try {
    const enc = new TextEncoder();
    // Device hardware entropy mix (screen res + hardware concurrency + user PIN)
    const entropy = (screen.width || 360) + "x" + (screen.height || 640) + "_" + (navigator.hardwareConcurrency || 4);
    const salt = enc.encode("df_salt_entropy_" + entropy);

    const baseKey = await crypto.subtle.importKey("raw", enc.encode(userPin || "0000"), "PBKDF2", false, ["deriveKey"]);
    return await crypto.subtle.deriveKey(
      { name: "PBKDF2", salt: salt, iterations: 100000, hash: "SHA-256" },
      baseKey,
      { name: "AES-GCM", length: 256 },
      false,
      ["encrypt", "decrypt"]
    );
  } catch (e) {
    return null;
  }
};

