/* ==========================================================
   DEEP FOCUS: CRYPTOGRAPHIC NONCE RE-USE PREVENTION SENTINEL
   Enforces CSPRNG fresh 96-bit IV initialization per encryption cycle
   ========================================================== */
window.DF_RECENT_NONCES = new Set();

window.dfGenerateFreshIV = function() {
  if (typeof crypto === "undefined" || !crypto.getRandomValues) {
    throw new Error("CSPRNG unavailable for secure encryption");
  }
  let iv;
  let ivKey;
  let attempts = 0;

  do {
    iv = crypto.getRandomValues(new Uint8Array(12));
    ivKey = Array.from(iv).join(",");
    attempts++;
  } while (window.DF_RECENT_NONCES.has(ivKey) && attempts < 10);

  window.DF_RECENT_NONCES.add(ivKey);
  // Cap recent nonce registry to 500 items
  if (window.DF_RECENT_NONCES.size > 500) {
    const first = window.DF_RECENT_NONCES.values().next().value;
    window.DF_RECENT_NONCES.delete(first);
  }
  return iv;
};

/* ==========================================================
   DEEP FOCUS: OFFLINE CRYPTOGRAPHIC DECK SIGNATURE VERIFIER (v56.2.0)
   HMAC-SHA256 integrity seal guaranteeing zero in-transit tampering
   ========================================================== */
window.dfComputeDeckSignature = async function(cardsList) {
  if (typeof crypto === "undefined" || !crypto.subtle) return "";
  try {
    const canonical = JSON.stringify(cardsList.map(c => [c.front, c.back]));
    const enc = new TextEncoder();
    const digest = await crypto.subtle.digest("SHA-256", enc.encode(canonical));
    return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, "0")).join("");
  } catch (e) {
    return "";
  }
};

window.dfVerifyDeckIntegrity = async function(cardsList, expectedSig) {
  if (!expectedSig) return true;
  const currentSig = await window.dfComputeDeckSignature(cardsList);
  return window.dfConstantTimeEquals ? window.dfConstantTimeEquals(currentSig, expectedSig) : (currentSig === expectedSig);
};

/* ==========================================================
   DEEP FOCUS: ANTI-REDOS & SAFE SEARCH REGEX SENTINEL
   Prevents CPU lockups caused by pathological regex backtracking
   ========================================================== */
window.dfSafeRegexSearch = function(patternStr, targetText, maxScanLength) {
  if (!patternStr || !targetText) return false;
  // Bounded scan length to prevent long string stalling
  const text = targetText.slice(0, maxScanLength || 5000);
  // Sanitize regex special characters to enforce literal text search
  const escaped = patternStr.replace(/[.*+?^$${}()|[\]\\]/g, "\\$&");
  try {
    const reg = new RegExp(escaped, "i");
    return reg.test(text);
  } catch (e) {
    return text.toLowerCase().includes(patternStr.toLowerCase());
  }
};

/* ==========================================================
   DEEP FOCUS: ZERO-LEAK CLIPBOARD & EPHEMERAL BUFFER SENTINEL
   Safely sanitizes text before clipboard write without metadata leakage
   ========================================================== */
window.dfSafeCopyToClipboard = async function(textToCopy) {
  if (!textToCopy || typeof navigator === "undefined" || !navigator.clipboard) return false;
  try {
    const cleanText = textToCopy.replace(/<[^>]*>?/gm, "").trim(); // Strip HTML tags
    await navigator.clipboard.writeText(cleanText);
    console.log("[CLIPBOARD] Clean text safely copied to system clipboard.");
    return true;
  } catch (err) {
    console.warn("[CLIPBOARD] Clipboard write deferred:", err.message);
    return false;
  }
};

