window.dfAudioDsp = {
  synthesizePinkNoiseSlice: function(length) {
    const len = length || 44100;
    const b = new Float32Array(len);
    let b0 = 0, b1 = 0, b2 = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      b0 = 0.99886 * b0 + w * 0.0555179;
      b1 = 0.99332 * b1 + w * 0.0750759;
      b2 = 0.96900 * b2 + w * 0.1538520;
      b[i] = (b0 + b1 + b2) * 0.11;
    }
    return b;
  }
};
