// --- Flashcard DOM Buttons & Persistence ---
window.dfRenderFlashcardRatingButtons =
  function(container, cardId, onRate) {
    if (!container || !container.appendChild) {
      return { status: 'NO_CONTAINER' };
    }
    container.textContent = "";
    const ratings = [
      { score: 1, label: 'Again' },
      { score: 2, label: 'Hard' },
      { score: 3, label: 'Good' },
      { score: 4, label: 'Easy' },
      { score: 5, label: 'Perfect' }
    ];
    ratings.forEach(function(r) {
      const b = document.createElement('button');
      b.className = 'flashcard-rating-btn';
      b.textContent = r.label;
      b.setAttribute('data-rating', r.score);
      b.style.minHeight = '44px';
      b.style.minWidth = '44px';
      b.onclick = function() {
        if (typeof onRate === 'function') {
          onRate(cardId, r.score);
        }
        window.dfSubmitFlashcardRating(
          cardId, r.score
        );
      };
      container.appendChild(b);
    });
    return {
      status: 'RATING_BUTTONS_ATTACHED',
      buttonCount: 5
    };
  };

window.dfSubmitFlashcardRating =
  function(cardId, score) {
    try {
      const k = 'df_flashcards_history';
      const raw = localStorage.getItem(k);
      const list = raw ? JSON.parse(raw) : [];
      list.push({
        id: cardId,
        score: score,
        time: Date.now()
      });
      localStorage.setItem(k, JSON.stringify(list));
      return { persisted: true, cardId: cardId };
    } catch(e) {
      return { persisted: false };
    }
  };


// --- MISSIONS M6618-M6627: Studio DSP Audio ---
window.dfStudioAudio = {
  ctx: null, nodes: [],
  getCtx: function() {
    if (!this.ctx) {
      const A = window.AudioContext ||
        window.webkitAudioContext;
      if (A) this.ctx = new A();
    }
    return this.ctx;
  },
  playAmbience: function(isRain) {
    const ctx = this.getCtx();
    if (!ctx) return;
    this.stop();
    if (ctx.state === 'suspended') ctx.resume();
    const len = Math.floor(ctx.sampleRate * 3);
    const buf = ctx.createBuffer(
      1, len, ctx.sampleRate
    );
    const d = buf.getChannelData(0);
    let last = 0.0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      last = (last + (0.02 * w)) / 1.02;
      d[i] = last * 3.5;
    }
    const src = ctx.createBufferSource();
    src.buffer = buf; src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = isRain ? 800 : 380;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.001, ctx.currentTime);
    const tE = ctx.currentTime + 1.2;
    g.gain.linearRampToValueAtTime(0.28, tE);
    src.connect(f); f.connect(g);
    g.connect(ctx.destination);
    src.start(); this.nodes.push(src, g);
  },
  playBinaural: function(diff) {
    const ctx = this.getCtx();
    if (!ctx) return;
    this.stop();
    if (ctx.state === 'suspended') ctx.resume();
    const oL = (globalThis.__dfNoopOsc ? globalThis.__dfNoopOsc() : { type:"sine", frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){}}, detune:{value:0,setValueAtTime(){}}, connect(d){return d||this;}, disconnect(){}, start(){}, stop(){} });
    const oR = (globalThis.__dfNoopOsc ? globalThis.__dfNoopOsc() : { type:"sine", frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},linearRampToValueAtTime(){}}, detune:{value:0,setValueAtTime(){}}, connect(d){return d||this;}, disconnect(){}, start(){}, stop(){} });
    oL.type = 'sine'; oR.type = 'sine';
    oL.frequency.value = 216;
    oR.frequency.value = 216 + (diff || 10);
    const m = ctx.createChannelMerger(2);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.001, ctx.currentTime);
    const tE2 = ctx.currentTime + 1.5;
    g.gain.linearRampToValueAtTime(0.18, tE2);
    oL.connect(m, 0, 0); oR.connect(m, 0, 1);
    m.connect(g); g.connect(ctx.destination);
    oL.start(); oR.start();
    this.nodes.push(oL, oR, g);
  },
  stop: function() {
    this.nodes.forEach(function(n) {
      try {
        if (n.stop) n.stop();
        if (n.disconnect) n.disconnect();
      } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
    });
    this.nodes = [];
  }
};
