// --- MISSIONS M6798-M6807: Wind Breeze DSP ---
window.dfWindBreeze = {
  activeWindNodes: [],
  playBreeze: function(ctx, masterGain) {
    if (!ctx || ctx.state === 'suspended') return;
    const len = Math.floor(ctx.sampleRate * 4);
    const buf = ctx.createBuffer(
      1, len, ctx.sampleRate
    );
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      last = (last + (0.02 * w)) / 1.02;
      d[i] = last * 2.8;
    }
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(
      320, ctx.currentTime
    );
    filter.Q.value = 1.8;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, ctx.currentTime);
    const tEnd = ctx.currentTime + 1.5;
    gain.gain.linearRampToValueAtTime(0.22, tEnd);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(masterGain || ctx.destination);
    src.start();
    this.activeWindNodes.push(src, gain);
  },
  stopBreeze: function() {
    this.activeWindNodes.forEach(function(n) {
      try {
        if (n.stop) n.stop();
        if (n.disconnect) n.disconnect();
      } catch (e) { if (typeof window !== "undefined" && window.__dfRecordError) window.__dfRecordError("catch", e); }
    });
    this.activeWindNodes = [];
  }
};
