      b.style.cssText = `padding:7px 11px;border-radius:8px;border:1px solid ${isCur ? '#2563eb' : '#cbd5e1'};background:${isCur ? '#2563eb' : '#ffffff'};color:${isCur ? '#ffffff' : '#0f172a'};font-size:11px;font-weight:800;cursor:pointer;`;
